INSERT INTO privacy_notices (notice_id, version, locale, title, purposes, legal_bases_supported, effective_at, published_by, status, content_summary, fiduciary_entity, grievance_officer_contact) VALUES ('HN-DPDP-NOTICE-2026-V2', '2.4.0', 'en-IN', 'HireNestOS Candidate & Workforce Personal Data Protection Notice (DPDP Act, 2023)', '["Candidate profile creation, resume parsing & SHA-256 deduplication","4-dimension JD skill matching & explainable recruiter screening","Authorised submission to mapped hiring clients with human recruiter approval","Interview scheduling, evaluation feedback & communication (Email / WhatsApp)"]'::jsonb, '["consent","voluntary_employment_use","contractual_processor_instruction"]'::jsonb, '2026-10-26T00:00:00.000Z', 'Data Protection & Governance Office (HireNest Workforce Pvt Ltd)', 'active', 'Explains categories of personal data collected (resume, contact details, employment history, skills, interview evaluations), specific recruitment purposes, Data Fiduciary/Processor responsibilities, AI Gateway PII redaction safeguards, retention windows, and how Data Principals can exercise rights of access, correction, consent withdrawal, erasure, and grievance redressal.', 'HireNest Workforce Private Limited (Technical Partner: AIKIND Private Limited)', 'dpo-grievance@hirenestworkforce.com') ON CONFLICT (notice_id) DO NOTHING;
INSERT INTO privacy_notices (notice_id, version, locale, title, purposes, legal_bases_supported, effective_at, published_by, status, content_summary, fiduciary_entity, grievance_officer_contact) VALUES ('HN-DPDP-VENDOR-2026-V1', '1.2.0', 'en-IN', 'Vendor Agency Candidate Representation & Notice Attestation Charter', '["Vendor representation attestation & candidate notice delivery confirmation","Ownership lock verification (30-day exclusivity window) & dispute resolution"]'::jsonb, '["consent","contractual_processor_instruction"]'::jsonb, '2026-09-15T00:00:00.000Z', 'HQ Compliance & Vendor Operations', 'active', 'Requires staffing vendors uploading candidate resumes to attest that the candidate has received the HireNestOS DPDP Notice and authorized submission to the specific requirement.', 'HireNest Workforce Private Limited', 'vendor-privacy@hirenestworkforce.com') ON CONFLICT (notice_id) DO NOTHING;
