INSERT INTO retention_policies (policy_id, data_category, purpose, trigger, duration_rule, duration_days, legal_hold_exception, legal_hold_reason, owner, version, status) VALUES ('RET-CAND-ACTIVE', 'Candidate Profiles & Uploaded Resumes', 'Active recruitment matching, career portal applications & talent pool sourcing', 'Last candidate interaction, application activity, or consent renewal', '24 months from last active interaction (or immediate upon erasure/withdrawal)', 730, false, NULL, 'HQ Talent Operations & DPO', '1.3', 'active') ON CONFLICT (policy_id) DO NOTHING;
INSERT INTO retention_policies (policy_id, data_category, purpose, trigger, duration_rule, duration_days, legal_hold_exception, legal_hold_reason, owner, version, status) VALUES ('RET-SUBMISSION-RECORD', 'Client Submissions & Vendor Ownership Locks', 'Commercial agency fee attribution, 30-day ownership governance & client audit', 'Requirement closure or final submission stage disposition', '36 months post requirement closure (statutory commercial dispute window)', 1095, true, 'Active vendor ownership dispute #DSP-2026-08 requires preserving submission timestamp metadata.', 'HQ Legal & Commercial Governance', '2.0', 'active') ON CONFLICT (policy_id) DO NOTHING;
INSERT INTO retention_policies (policy_id, data_category, purpose, trigger, duration_rule, duration_days, legal_hold_exception, legal_hold_reason, owner, version, status) VALUES ('RET-AI-TELEMETRY', 'AI Gateway Prompts & Screening Evaluations', 'Explainable AI auditability, rate-limit enforcement & quality assurance', 'AI Gateway execution timestamp', 'Zero raw PII persisted in prompts; advisory evaluation artifacts retained 180 days', 180, false, NULL, 'AIKIND Engineering & Security', '1.1', 'active') ON CONFLICT (policy_id) DO NOTHING;
INSERT INTO retention_policies (policy_id, data_category, purpose, trigger, duration_rule, duration_days, legal_hold_exception, legal_hold_reason, owner, version, status) VALUES ('RET-AUDIT-LEDGER', 'Privacy & Security Audit Events (Minimal Non-PII)', 'DPDP Act accountability, breach investigation & regulatory evidence', 'Audit event creation', '60 months immutable metadata retention (no raw resume text or contact PII)', 1825, false, NULL, 'Chief Information Security Officer', '1.0', 'active') ON CONFLICT (policy_id) DO NOTHING;
