INSERT INTO privacy_incidents (incident_id, tenant_id, title, detected_at, severity, affected_systems, affected_records_estimate, assessment, containment, notification_status, accountable_owner, closure_evidence) VALUES ('INC-DPDP-2026-01', 'vendor_global_staffing', 'Blocked Cross-Tenant Bulk Candidate Export Attempt by Unauthorised Vendor Role', '2026-10-24T17:22:10.000Z', 'medium', '["Server-Side Sharing & Export Guard","Vendor Candidate Pool API"]'::jsonb, 0, 'Vendor recruiter session attempted to export candidate contact records belonging to another tenant ID. Server-side ABAC Sharing Guard intercepted and denied the request with HTTP 403 before any PII left the database.', 'Request blocked automatically; session token rotated; vendor admin notified to review recruiter role permissions.', 'not_required', 'AIKIND Security Operations & HireNest DPO', 'Audit Correlation ID corr_99281a7b confirms 0 bytes exfiltrated.') ON CONFLICT (incident_id) DO NOTHING;
